#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""Fix only breadcrumb icon and statusbar/card width on Day 8 ticket/FAQ details."""
from pathlib import Path
import ast
import datetime
import sys

ROOT = Path.cwd()
ADDON = ROOT / "custom_addons" / "it_helpdesk"
TARGET = ADDON / "static/src/ui/helpdesk_detail.scss"

# Exact v2 version authored previously. No manifest/XML changes.
REVISED = '// Day 8 detail v2: clean native Odoo form pages without extra floating cards.\n// All selectors are scoped to the Helpdesk app and its ticket/FAQ forms.\nbody.o_it_helpdesk_sidebar_active {\n  .o_action_manager {\n    .o_it_helpdesk_ticket_form,\n    .o_it_helpdesk_faq_form {\n      --it-detail-gutter: clamp(16px, 2vw, 28px);\n      --it-detail-border: #e1e7f0;\n      --it-detail-ink: #17233c;\n      --it-detail-muted: #64748b;\n\n      // A detail view has no "New" button. List creation stays enabled.\n      .o_control_panel .o_form_button_create {\n        display: none !important;\n      }\n\n      // One clear hierarchy: back link above a real page title.\n      .o_control_panel .o_breadcrumb {\n        align-items: flex-start;\n        gap: 5px;\n        min-width: 0;\n\n        > .breadcrumb {\n          display: flex;\n          flex-wrap: wrap;\n          align-items: center;\n          margin: 0;\n          padding: 0;\n          line-height: 1.2;\n\n          .breadcrumb-item.o_back_button {\n            display: inline-flex;\n            align-items: center;\n            padding: 0;\n            cursor: pointer;\n\n            &::before {\n              display: none;\n            }\n\n            > a {\n              display: inline-flex;\n              align-items: center;\n              justify-content: center;\n              flex: 0 0 36px;\n              width: 36px;\n              height: 36px;\n              padding: 0;\n              overflow: hidden;\n              border: 1px solid #d9e6f7;\n              border-radius: 9px;\n              background: #f1f6fd;\n              color: #315b8a !important;\n              font-size: 0 !important; // Keep the accessible link text, visually show only the icon.\n              line-height: 1;\n              text-decoration: none;\n\n              &::before {\n                content: "\\2190";\n                font-size: 19px;\n                font-weight: 700;\n                line-height: 1;\n              }\n\n              &:hover,\n              &:focus-visible {\n                background: #e6f0ff;\n                border-color: #a4c4ef;\n              }\n            }\n          }\n        }\n\n        .o_last_breadcrumb_item {\n          font-size: clamp(1.15rem, 1.5vw, 1.45rem);\n          font-weight: 800;\n          line-height: 1.35;\n          color: var(--it-detail-ink);\n        }\n      }\n\n      // Don\'t create another floating border around the native action bar.\n      .o_form_statusbar {\n        box-sizing: border-box;\n        display: flex;\n        align-items: center;\n        flex-wrap: wrap;\n        width: 100% !important;\n        min-width: 0;\n        max-width: 100% !important;\n        margin: 0 !important; // Match the sheet\'s outer edges, not an extra inset.\n        padding: 12px 16px !important;\n        border: 1px solid var(--it-detail-border);\n        border-bottom: 0;\n        border-radius: 12px 12px 0 0;\n        background: #ffffff;\n        box-shadow: none;\n\n        .o_statusbar_buttons {\n          display: flex;\n          align-items: center;\n          flex-wrap: wrap;\n          width: auto;\n          max-width: 100%;\n          min-width: 0;\n          margin: 0;\n          padding: 0;\n          gap: 8px;\n          background: transparent;\n\n          .btn {\n            flex: 0 0 auto;\n            max-width: 100%;\n            min-height: 35px;\n            margin: 0 !important;\n            padding: 7px 12px;\n            border-radius: 8px;\n            white-space: normal;\n          }\n        }\n      }\n\n      // Native Odoo form layout remains intact; stretch its content area.\n      .o_form_renderer,\n      .o_form_sheet_bg {\n        min-width: 0;\n        max-width: none;\n      }\n\n      .o_form_sheet_bg {\n        box-sizing: border-box;\n        width: 100%;\n        padding: 0 0 24px;\n        background: #f3f6fb;\n      }\n\n      .o_form_sheet {\n        box-sizing: border-box;\n        width: 100%;\n        max-width: none;\n        margin: 0;\n        padding: clamp(20px, 2vw, 30px);\n        border: 1px solid var(--it-detail-border);\n        border-radius: 0 0 12px 12px;\n        background: #fff;\n        box-shadow: 0 7px 22px rgba(23, 35, 60, 0.045);\n      }\n\n      // No huge blank space between field sections.\n      .o_form_sheet .o_group {\n        min-width: 0;\n        margin-bottom: 14px;\n      }\n\n      .o_form_sheet .o_group .o_group {\n        margin-bottom: 0;\n      }\n\n      .o_form_sheet .o_horizontal_separator {\n        margin: 0 0 12px;\n        padding: 0 0 9px;\n        border-bottom: 1px solid var(--it-detail-border);\n        color: var(--it-detail-ink);\n        font-size: 1.02rem;\n        font-weight: 750;\n      }\n\n      .o_form_sheet .o_form_label {\n        color: var(--it-detail-muted);\n        font-weight: 650;\n      }\n\n      .o_form_sheet .o_field_widget {\n        min-width: 0;\n      }\n    }\n\n    // Ticket history should fill the sheet and remain readable.\n    .o_it_helpdesk_ticket_form {\n      .o_it_helpdesk_history_section {\n        min-width: 0;\n\n        .o_field_x2many,\n        .o_list_renderer {\n          min-width: 0;\n          width: 100%;\n          max-width: 100%;\n        }\n\n        .o_list_renderer {\n          overflow-x: auto;\n          border: 1px solid var(--it-detail-border);\n          border-radius: 9px;\n        }\n\n        .o_list_table {\n          width: 100%;\n          min-width: 690px;\n          table-layout: auto;\n\n          th, td {\n            padding: 10px 12px;\n            vertical-align: top;\n          }\n\n          td {\n            white-space: normal;\n            overflow-wrap: anywhere;\n            line-height: 1.45;\n          }\n        }\n      }\n\n      // Treat the chatter as the second reading column, not a disconnected page.\n      .o-mail-ChatterContainer {\n        min-width: 0;\n        border-left: 1px solid #e6ebf2;\n        background: #fff;\n      }\n    }\n\n    // FAQ reading/editing: ample answer space with consistent paragraph rhythm.\n    .o_it_helpdesk_faq_public_form,\n    .o_it_helpdesk_faq_management_form {\n      .o_it_helpdesk_faq_answer,\n      .o_it_helpdesk_faq_answer .o_field_widget {\n        display: block;\n        width: 100%;\n        max-width: 100%;\n        min-width: 0;\n        overflow-wrap: anywhere;\n        line-height: 1.7;\n      }\n\n      .o_it_helpdesk_faq_answer textarea {\n        min-height: 170px;\n        resize: vertical;\n      }\n    }\n\n    @media (max-width: 991.98px) {\n      .o_it_helpdesk_ticket_form,\n      .o_it_helpdesk_faq_form {\n        --it-detail-gutter: 12px;\n\n        .o_form_statusbar {\n          padding: 10px 12px !important;\n        }\n\n        .o_form_sheet {\n          padding: 16px;\n        }\n      }\n    }\n  }\n}\n'

def main():
    if not TARGET.is_file():
        raise RuntimeError("Run from the IT-Helpdesk repository root; helpdesk_detail.scss missing.")
    original = TARGET.read_text(encoding="utf-8")
    if original == REVISED:
        print("Already applied; no changes.")
        return
    if "Day 8 detail v2:" not in original or "margin: 0 var(--it-detail-gutter) !important;" not in original:
        raise RuntimeError("Unexpected stylesheet version. No files changed; share its current contents.")
    if original.count("margin: 0 var(--it-detail-gutter) !important;") != 1:
        raise RuntimeError("Ambiguous style blocks. No files changed.")
    backups = ROOT / "backups" / "day08_detail_alignment"
    backups.mkdir(parents=True, exist_ok=True)
    backup = backups / ("helpdesk_detail_" + datetime.datetime.now().strftime("%Y%m%d_%H%M%S_%f") + ".scss.bak")
    backup.write_text(original, encoding="utf-8")
    TARGET.write_text(REVISED, encoding="utf-8")
    print("Updated:", TARGET.relative_to(ROOT))
    print("Backup:", backup.relative_to(ROOT))
    print("Done. No manifest, XML or Python model edits.")

if __name__ == "__main__":
    try:
        main()
    except Exception as exc:
        print("ERROR:", exc, file=sys.stderr)
        sys.exit(1)
